/* H-17 K04 original target: exhaustive two 33-dimensional affine coupon
 * families from hypothetical copied ACK2 native stages 1178 and 1405.
 * Data files generated by agent38 Python source SFT (132 original source
 * packets, selected p951 quartet withheld). C11 OpenSSL + OpenMP.
 * Args: data_dir begin end threads.
 */
#include <stdint.h>
#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
#include <omp.h>
#define DIM 33
#define BYTES 16
#define TOTAL (UINT64_C(1)<<DIM)
static const char *TARGET="930A52A1BAB97CA2966332137C99E99298EA6182FB32AB63A3421DFB4FD8C9E0";
static uint8_t base[2][BYTES],delta[DIM][BYTES],want[32],control[2][32];
static uint8_t hex(char c){
 if(c>='0'&&c<='9')return (uint8_t)(c-'0');
 if(c>='A'&&c<='F')return (uint8_t)(c-'A'+10);
 fprintf(stderr,"bad hex char %02X\n",(unsigned char)c);exit(4);
}
static void decode(const char *s,uint8_t *out,int len){
 if((int)strlen(s)!=2*len){fprintf(stderr,"bad hex length\n");exit(4);}
 for(int i=0;i<len;i++)out[i]=(uint8_t)(16*hex(s[2*i])+hex(s[2*i+1]));
}
static void xdelta(uint8_t out[BYTES],const uint8_t mask[BYTES]){
 for(int j=0;j<BYTES;j++)out[j]^=mask[j];
}
static void load(const char *folder,int stage,int index){
 char path[1024],token[40];
 snprintf(path,sizeof(path),"%s/k04_stage%d_affine.dat",folder,stage);
 FILE *f=fopen(path,"r");if(!f){perror(path);exit(4);}
 if(fscanf(f,"%32s",token)!=1)exit(4);
 decode(token,base[index],BYTES);
 for(int j=0;j<DIM;j++){
  if(fscanf(f,"%32s",token)!=1){fprintf(stderr,"missing delta %d in %s\n",j,path);exit(4);}
  uint8_t line[BYTES];decode(token,line,BYTES);
  if(index==0)memcpy(delta[j],line,BYTES);
  else if(memcmp(delta[j],line,BYTES)){fprintf(stderr,"stage delta mismatch %d\n",j);exit(4);}
 }
 if(fscanf(f,"%32s",token)==1){fprintf(stderr,"extra affine line\n");exit(4);}
 fclose(f);
}
int main(int argc,char**argv){
 if(argc!=5){fprintf(stderr,"usage: data_dir begin end threads\n");return 4;}
 uint64_t begin=strtoull(argv[2],NULL,10),end=strtoull(argv[3],NULL,10);
 int threads=atoi(argv[4]);
 if(begin>=end||end>TOTAL||threads<1||threads>32)return 4;
 load(argv[1],1178,0);load(argv[1],1405,1);
 decode(TARGET,want,32);
 if(!memcmp(base[0]+8,base[1]+8,8)){fprintf(stderr,"overlapping coset suffix\n");return 4;}
 const uint64_t marker=UINT64_C(0x123456789),mg=marker^(marker>>1);
 for(int stage=0;stage<2;stage++){
  uint8_t planted[BYTES];memcpy(planted,base[stage],BYTES);
  for(int j=0;j<DIM;j++)if((mg>>j)&1)xdelta(planted,delta[j]);
  SHA256(planted,BYTES,control[stage]);
  if(!memcmp(want,control[stage],32)){fprintf(stderr,"marker matches original!\n");return 4;}
 }
 uint64_t original[2]={0,0},positive[2]={0,0};
 double t=omp_get_wtime();
 #pragma omp parallel num_threads(threads) reduction(+:original[:2],positive[:2])
 {
  int tid=omp_get_thread_num(),nthreads=omp_get_num_threads();
  uint64_t left=begin+(end-begin)*(uint64_t)tid/(uint64_t)nthreads;
  uint64_t right=begin+(end-begin)*(uint64_t)(tid+1)/(uint64_t)nthreads;
  if(left<right){
   uint8_t current[2][BYTES],digest[32];
   uint64_t initial=left^(left>>1);
   for(int stage=0;stage<2;stage++){
    memcpy(current[stage],base[stage],BYTES);
    for(int j=0;j<DIM;j++)if((initial>>j)&1)xdelta(current[stage],delta[j]);
   }
   for(uint64_t i=left;i<right;i++){
    for(int stage=0;stage<2;stage++){
     SHA256(current[stage],BYTES,digest);
     if(!memcmp(digest,want,32)){
      original[stage]++;
      #pragma omp critical
      {
       printf("ORIGINAL_K04_MATCH stage=%d i=%" PRIu64 " component=",stage?1405:1178,i);
       for(int k=0;k<BYTES;k++)printf("%02X",current[stage][k]);
       puts("");fflush(stdout);
      }
     }
     if(!memcmp(digest,control[stage],32))positive[stage]++;
    }
    if(i+1<right){
     int j=__builtin_ctzll(i+1);
     xdelta(current[0],delta[j]);xdelta(current[1],delta[j]);
    }
   }
  }
 }
 uint64_t expect=begin<=marker&&marker<end?1:0;
 printf("DONE begin=%" PRIu64 " end=%" PRIu64 " states=%" PRIu64 " complete_hashes=%" PRIu64
 " K04_stage1178=%" PRIu64 " K04_stage1405=%" PRIu64
 " synthetic1178=%" PRIu64 " synthetic1405=%" PRIu64 " expect_each=%" PRIu64 " sec=%.3f\n",
 begin,end,end-begin,2*(end-begin),original[0],original[1],positive[0],positive[1],expect,omp_get_wtime()-t);
 return positive[0]!=expect||positive[1]!=expect?3:original[0]||original[1]?2:0;
}
